ValidationRule.errorConditionFormula:
AND( /* Record type is constant */ RecordType.DeveloperName = 'ACH_Bounce', /* Not applicable to Portfolio Management Users Amber Conley and Jackie Schmidt or users with accounting role*/ NOT(OR( $User.Id='00580000004QkkA', $User.Id='00580000006OfoO', $User.Id='0053400000ALqtt', $User.Id='00580000003edxL', $User.Id='00534000008caXs', $User.UserRoleId='00E80000001jt0B')), /* Or conditions */ OR( /* Condition One - Collections Stage and Status are changed, but Sum Note is not. */ AND( NOT(ISCHANGED( New_Sum_Note__c )), OR( ISCHANGED(New_Collections_Status__c), ISCHANGED(New_Collections_Stage__c))),
/* Condition Two - Collections Stage and Status are changed but Sum Note is blank. */ AND( OR( ISCHANGED(New_Collections_Status__c), ISCHANGED(New_Collections_Stage__c)), ISBLANK(New_Sum_Note__c)),
/* Condition Three - When New Collections Stage or Status <> Blank and New Sum Note is blank. */
AND( ISBLANK(New_Sum_Note__c), OR( NOT(ISBLANK(TEXT(New_Collections_Status__c))), NOT(ISBLANK(TEXT(New_Collections_Stage__c))))) ) )
